// VIOC_civ_vehicles.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
// Estaciona vehiculos civiles VACIOS y ABIERTOS en los pueblos: a la orilla de calles del pueblo, fuera de
// edificios y a mas de 55 m del deposito. 2 en pueblos chicos, 3 medianos, 4 grandes (segun maxSV del pueblo).
// Cada 25 min repone los que falten (y borra los nuestros inservibles) en pueblos sin jugadores a menos de 800 m.
// Usa coches civiles de CUP si estan cargados; si no, los civiles del juego base (se comprueba cada clase).
// Un vehiculo vacio es del bando civil: no cuenta para capturar pueblos ni los activa.
// Solo corre en el servidor (jugando solo, tu PC es el servidor).
if (!isServer) exitWith {};

//--- Ajustes
VIOC_CIV_TOPUP_DELAY  = 1500;   // segundos entre reposiciones
VIOC_CIV_PLAYER_RANGE = 800;    // no reponer ni borrar si hay un jugador a menos de esta distancia
VIOC_CIV_MAX_TOTAL    = 150;    // tope de vehiculos de este script vivos a la vez
VIOC_CIV_BOATS        = true;   // 1 bote civil si hay agua profunda cerca del pueblo
VIOC_CIV_SKIP         = ["military", "base", "radio", "comms", " range"]; // lugares militares: sin civiles

//--- Espera a que existan los pueblos y a que termine la carga del servidor (incluida la partida guardada)
waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Towns"} && {missionNamespace getVariable ["CTI_Server_Loaded", false]}};
sleep 15;

//--- [clase, peso, clase, peso...] -> solo clases que existen y son publicas
VIOC_CIV_fnc_filter = {
    private _out = [];
    for "_i" from 0 to ((count _this) - 2) step 2 do {
        private _cfg = configFile >> "CfgVehicles" >> (_this select _i);
        if (isClass _cfg && {getNumber (_cfg >> "scope") == 2}) then {
            _out pushBack (configName _cfg);
            _out pushBack (_this select (_i + 1));
        };
    };
    _out
};

private _world = toLower worldName;
private _vanilla = ["C_Offroad_01_F",1, "C_Hatchback_01_F",1, "C_SUV_01_F",0.6, "C_Van_01_transport_F",0.7, "C_Van_01_box_F",0.4, "C_Truck_02_transport_F",0.2, "C_Quadbike_01_F",0.4];
private _cars = switch (true) do {
    case (_world in ["takistan", "zargabad", "mountains_acr", "shapur_baf", "desert_e"]): {[
        "CUP_C_Lada_TK_CIV",1, "CUP_C_Lada_TK2_CIV",1, "CUP_C_Lada_GreenTK_CIV",1, "CUP_C_Volha_Gray_TKCIV",1,
        "CUP_C_Volha_Blue_TKCIV",1, "CUP_C_UAZ_Unarmed_TK_CIV",0.8, "CUP_C_UAZ_Open_TK_CIV",0.6, "CUP_C_Datsun",0.8,
        "CUP_C_Datsun_Covered",0.6, "CUP_C_Datsun_Plain",0.6, "CUP_C_Datsun_4seat",0.6, "CUP_C_LR_Transport_CTK",0.5,
        "CUP_C_SUV_TK",0.4, "CUP_C_TT650_TK_CIV",0.3, "CUP_C_V3S_Open_TKC",0.3, "CUP_C_V3S_Covered_TKC",0.3,
        "CUP_C_Ikarus_TKC",0.15, "CUP_C_Bus_City_TKCIV",0.1
    ]};
    case (_world in ["tanoa"]): {[
        "C_Offroad_02_unarmed_F",1, "C_Offroad_01_F",1, "C_Van_01_transport_F",0.7, "C_Hatchback_01_F",0.7,
        "C_Quadbike_01_F",0.4, "C_Truck_02_transport_F",0.2, "CUP_C_Datsun",0.7, "CUP_C_Datsun_Tubeframe",0.4,
        "CUP_C_Pickup_unarmed_CIV",0.6, "CUP_C_SUV_CIV",0.5, "CUP_C_TT650_CIV",0.3
    ]};
    default {[
        "CUP_C_Skoda_White_CIV",1, "CUP_C_Skoda_Red_CIV",1, "CUP_C_Skoda_Blue_CIV",1, "CUP_C_Skoda_Green_CIV",0.7,
        "CUP_C_Golf4_random_Civ",1, "CUP_C_Octavia_CIV",0.8, "CUP_C_Lada_White_CIV",0.7, "CUP_C_Lada_Red_CIV",0.7,
        "CUP_C_Volha_CR_CIV",0.6, "CUP_C_S1203_CIV",0.6, "CUP_C_Datsun",0.6, "CUP_C_Datsun_Plain",0.5,
        "CUP_C_Datsun_4seat",0.5, "CUP_C_SUV_CIV",0.4, "CUP_C_Pickup_unarmed_CIV",0.5, "CUP_C_Tractor_CIV",0.25,
        "CUP_C_Tractor_Old_CIV",0.2, "CUP_C_TT650_CIV",0.3, "CUP_C_Ural_Civ_01",0.15, "CUP_C_Ural_Open_Civ_01",0.15,
        "CUP_C_Ikarus_Chernarus",0.1, "CUP_C_Bus_City_CRCIV",0.1
    ]};
};
if (_world in ["malden", "altis", "stratis"]) then {_cars append _vanilla};
VIOC_CIV_CARS = _cars call VIOC_CIV_fnc_filter;
if (VIOC_CIV_CARS isEqualTo []) then {VIOC_CIV_CARS = _vanilla call VIOC_CIV_fnc_filter};
VIOC_CIV_BOATPOOL = ["CUP_C_Fishing_Boat_Chernarus",0.6, "CUP_C_Zodiac_CIV",0.6, "CUP_C_PBX_CIV",0.6, "C_Boat_Civil_01_F",1, "C_Rubberboat",0.8] call VIOC_CIV_fnc_filter;
if (VIOC_CIV_CARS isEqualTo []) exitWith {diag_log "VIOC civ_vehicles: no hay clases de vehiculos civiles disponibles"};

VIOC_CIV_LIST = [];

//--- Cuantos vehiculos le tocan a un pueblo (0 = ninguno)
VIOC_CIV_fnc_quota = {
    params ["_town"];
    private _name = toLower (_town getVariable ["cti_town_name", ""]);
    if ((VIOC_CIV_SKIP findIf {(_name find _x) >= 0}) >= 0) exitWith {0};
    ((round ((_town getVariable ["cti_town_maxSV", 60]) / 30)) max 2) min 4
};

//--- Tramos de calle del pueblo (sin puentes ni senderos), guardados en el pueblo
VIOC_CIV_fnc_roads = {
    params ["_town", "_center", "_rMax"];
    private _roads = _town getVariable ["vioc_civ_roads", []];
    if (_roads isEqualTo []) then {
        private _all = (_center nearRoads _rMax) select {((_x distance2D _center) > 55) && {!((getRoadInfo _x) param [8, false])}};
        _roads = _all select {(((getRoadInfo _x) param [0, ""]) in ["ROAD", "MAIN ROAD", "TRACK"]) && {!((getRoadInfo _x) param [2, false])}};
        if (_roads isEqualTo []) then {_roads = _all};
        _town setVariable ["vioc_civ_roads", _roads];
    };
    _roads
};

//--- Lugar libre a la orilla de una calle, lejos (15 m) de campamentos/defensas del pueblo: [posicion, direccion] o []
VIOC_CIV_fnc_landSpot = {
    params ["_roads", "_class", "_avoid"];
    private _spot = [];
    private _try = 0;
    while {(_spot isEqualTo []) && {_try < 16} && {_roads isNotEqualTo []}} do {
        _try = _try + 1;
        private _road = selectRandom _roads;
        private _ri = getRoadInfo _road;
        private _beg = _ri param [6, []];
        private _end = _ri param [7, []];
        private _dir = if (((count _beg) > 1) && {(count _end) > 1} && {(_beg distance2D _end) > 0.5}) then {_beg getDir _end} else {
            private _con = roadsConnectedTo _road;
            if (_con isEqualTo []) then {getDir _road} else {_road getDir (_con select 0)}
        };
        private _off = ((((_ri param [1, 6]) / 2) + 0.8) max 2.5) min 7;
        private _p = (getPosATL _road) getPos [_off, _dir + (selectRandom [90, -90])];
        private _fp = _p findEmptyPosition [0, 5, _class];
        if (_fp isNotEqualTo []) then {
            private _asl = AGLToASL _fp;
            if (!(surfaceIsWater _fp)
                && {((surfaceNormal _fp) select 2) > 0.95}
                && {(_fp nearEntities [["LandVehicle", "Ship"], 10]) isEqualTo []}
                && {(lineIntersectsSurfaces [_asl vectorAdd [0, 0, 25], _asl vectorAdd [0, 0, 0.6], objNull, objNull, true, 1, "GEOM", "NONE"]) isEqualTo []}
                && {(_avoid findIf {(_x distance2D _fp) < 15}) < 0}
                && {(allPlayers findIf {(_x distance2D _fp) < 150}) < 0}
                && {(_try > 10) || {(nearestTerrainObjects [_fp, ["HOUSE", "BUILDING"], 35, false, true]) isNotEqualTo []}}
            ) then {
                _spot = [_fp, _dir + (selectRandom [0, 180])];
            };
        };
    };
    _spot
};

//--- Agua de mas de 2.5 m de fondo con costa a 60 m: posicion o []
VIOC_CIV_fnc_waterSpot = {
    params ["_center", "_r"];
    private _spot = [];
    private _try = 0;
    while {(_spot isEqualTo []) && {_try < 40}} do {
        _try = _try + 1;
        private _p = _center getPos [80 + random (_r - 80), random 360];
        if ((surfaceIsWater _p)
            && {(getTerrainHeightASL _p) < -2.5}
            && {([0, 60, 120, 180, 240, 300] findIf {!(surfaceIsWater (_p getPos [60, _x]))}) >= 0}
            && {(_p nearEntities [["Ship", "LandVehicle"], 20]) isEqualTo []}
            && {(allPlayers findIf {(_x distance2D _p) < 150}) < 0}
        ) then {
            _spot = [_p select 0, _p select 1, 0];
        };
    };
    _spot
};

//--- Crea un vehiculo civil vacio y abierto
VIOC_CIV_fnc_spawn = {
    params ["_class", "_pos", "_dir"];
    private _veh = createVehicle [_class, _pos, [], 0, "CAN_COLLIDE"];
    _veh allowDamage false;
    _veh setDir _dir;
    if !(_veh isKindOf "Ship") then {_veh setPosATL [_pos select 0, _pos select 1, 0.15]};
    _veh lock 0;
    _veh setFuel (0.35 + random 0.5);
    _veh setVariable ["vioc_civ", true];
    if (!isNil "VIOC_ZEUS") then {VIOC_ZEUS addCuratorEditableObjects [[_veh], false]};
    VIOC_CIV_LIST pushBack _veh;
    _veh spawn {sleep 10; if (alive _this) then {_this allowDamage true}};
    _veh
};

//--- Vehiculos civiles vacios y utiles cerca (cuenta tambien los restaurados de la partida guardada)
VIOC_CIV_fnc_countNear = {
    params ["_pos", "_r", "_types"];
    {
        (canMove _x)
        && {((vectorUp _x) select 2) > 0.5}
        && {((crew _x) findIf {alive _x}) < 0}
        && {getNumber (configFile >> "CfgVehicles" >> (typeOf _x) >> "side") == 3}
    } count (_pos nearEntities [_types, _r])
};

//--- Borra los nuestros que quedaron inservibles o volcados, si no hay jugadores cerca
VIOC_CIV_fnc_cleanup = {
    {
        private _v = _x;
        if ((alive _v)
            && {!(canMove _v) || {((vectorUp _v) select 2) < 0.5}}
            && {((crew _v) findIf {alive _x}) < 0}
            && {(allPlayers findIf {(_x distance2D _v) < VIOC_CIV_PLAYER_RANGE}) < 0}
        ) then {
            deleteVehicle _v;
        };
    } forEach +VIOC_CIV_LIST;
    VIOC_CIV_LIST = VIOC_CIV_LIST select {(!isNull _x) && {alive _x}};
};

//--- Llena un pueblo hasta su cuota
VIOC_CIV_fnc_fillTown = {
    params ["_town", "_first"];
    private _quota = [_town] call VIOC_CIV_fnc_quota;
    if (_quota < 1) exitWith {};
    private _center = getPosATL _town;
    if (!_first && {(allPlayers findIf {(_x distance2D _center) < VIOC_CIV_PLAYER_RANGE}) >= 0}) exitWith {};
    private _rMax = (((_town getVariable ["cti_town_range", 550]) * 0.6) min 350) max 150;
    private _roads = [_town, _center, _rMax] call VIOC_CIV_fnc_roads;
    private _avoid = ((_town getVariable ["cti_town_camps", []]) + (_town getVariable ["cti_town_defenses", []]) + (_town getVariable ["cti_town_mortars", []])) select {!isNull _x};
    private _missing = _quota - ([_center, _rMax, ["Car", "Motorcycle"]] call VIOC_CIV_fnc_countNear);
    for "_i" from 1 to _missing do {
        if ((count VIOC_CIV_LIST) >= VIOC_CIV_MAX_TOTAL) exitWith {};
        private _class = selectRandomWeighted VIOC_CIV_CARS;
        private _spot = [_roads, _class, _avoid] call VIOC_CIV_fnc_landSpot;
        if (_spot isNotEqualTo []) then {[_class, _spot select 0, _spot select 1] call VIOC_CIV_fnc_spawn};
        sleep 0.2;
    };
    if (VIOC_CIV_BOATS
        && {VIOC_CIV_BOATPOOL isNotEqualTo []}
        && {(count VIOC_CIV_LIST) < VIOC_CIV_MAX_TOTAL}
        && {([_center, _rMax + 150, ["Ship"]] call VIOC_CIV_fnc_countNear) < 1}
    ) then {
        private _wp = [_center, _rMax + 150] call VIOC_CIV_fnc_waterSpot;
        if (_wp isNotEqualTo []) then {[selectRandomWeighted VIOC_CIV_BOATPOOL, _wp, random 360] call VIOC_CIV_fnc_spawn};
    };
};

//--- Primera pasada (tambien despues de cargar una partida guardada) y reposicion periodica
{[_x, true] call VIOC_CIV_fnc_fillTown; sleep 0.3} forEach CTI_Towns;
diag_log format ["VIOC civ_vehicles: %1 vehiculos civiles en %2 pueblos (%3, %4 clases)", count VIOC_CIV_LIST, count CTI_Towns, worldName, (count VIOC_CIV_CARS) / 2];

while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
    sleep VIOC_CIV_TOPUP_DELAY;
    call VIOC_CIV_fnc_cleanup;
    {[_x, false] call VIOC_CIV_fnc_fillTown; sleep 0.3} forEach CTI_Towns;
};
